import { ICON_PATHS, type IconName } from './icons.generated';

export type { IconName };

export interface IconProps {
  name: IconName;
  size?: number;
  filled?: boolean;
  className?: string;
}

/** Inline Material Symbols (Outlined 400) SVG; paths are generated by `npm run gen:icons`. */
export function Icon({ name, size = 24, filled = false, className }: IconProps) {
  const p = ICON_PATHS[name];
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 -960 960 960"
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      style={{ flexShrink: 0 }}
    >
      <path d={filled ? p.fill : p.outline} />
    </svg>
  );
}
